      "policy_source_id": "q4",
      "interpretation": "Customers with an active loyalty plan receive a 10% discount on bill payments; the discount must be applied to the amount charged. This is a REQUIRE condition: when loyalty_plan is 'active', the charged amount must equal amount_due * 0.9.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q4",
      "interpretation": "The agent should not make up any information or knowledge not provided by the user or the tools. All parameters in the pay_bill call must be grounded in tool evidence (bill ownership, payment method ownership, amount calculation).",
      "modality": "FORBID"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "h4",
      "actor": "system",
      "role": "tool_result",
      "fact": "Customer C2044 (Dana Whitfield) has bill_ids ['B3301', 'B3302'] and payment_methods [{'id': 'pm_card_7781', 'type': 'card'}]"
    },
    {
      "source_id": "h7",
      "actor": "system",
      "role": "tool_result",
      "fact": "Bill B3301 has amount_due='45.00' and loyalty_plan='active'"
    },
